print("files:", os.listdir(d))
# legacy sqlite migration (both old schemas)
for schema, ins in [("CREATE TABLE kv (key TEXT PRIMARY KEY NOT NULL, value TEXT NOT NULL) WITHOUT ROWID", "INSERT INTO kv VALUES ('a','1')"),
