    c = sqlite3.connect(q); c.execute(schema); c.execute(ins); c.commit(); c.close()
    s = Store(q); print("migrated:", s.namespaces(), s.get("a", ns=s.namespaces()[0])); s.close()
    print("is text now:", open(q,"rb").read()[:1] == b"{")
# empty file and malformed file
e = os.path.join(tempfile.mkdtemp(), "e.kv"); open(e,"w").close(); s = Store(e); print("empty ok:", s.keys()); s.close()
m = os.path.join(tempfile.mkdtemp(), "m.kv"); open(m,"w").write("{oops"); 
try: Store(m)
except ValueError as ex: print("malformed:", ex)
EOF

